   302→## src/hooks/useDashboardData.ts
   303→```
   304→import { useState, useEffect, useMemo, useCallback } from 'react';
   305→import type { GewohnheitenVerwaltung, TaeglicherCheckIn, TaeglicheEintraege } from '@/types/app';
   306→import { LivingAppsService } from '@/services/livingAppsService';
   307→
   308→export function useDashboardData() {
   309→  const [gewohnheitenVerwaltung, setGewohnheitenVerwaltung] = useState<GewohnheitenVerwaltung[]>([]);
   310→  const [taeglicherCheckIn, setTaeglicherCheckIn] = useState<TaeglicherCheckIn[]>([]);
   311→  const [taeglicheEintraege, setTaeglicheEintraege] = useState<TaeglicheEintraege[]>([]);
   312→  const [loading, setLoading] = useState(true);
   313→  const [error, setError] = useState<Error | null>(null);
   314→
   315→  const fetchAll = useCallback(async () => {
   316→    setError(null);
   317→    try {
   318→      const [gewohnheitenVerwaltungData, taeglicherCheckInData, taeglicheEintraegeData] = await Promise.all([
   319→        LivingAppsService.getGewohnheitenVerwaltung(),
   320→        LivingAppsService.getTaeglicherCheckIn(),
   321→        LivingAppsService.getTaeglicheEintraege(),
   322→      ]);
   323→      setGewohnheitenVerwaltung(gewohnheitenVerwaltungData);
   324→      setTaeglicherCheckIn(taeglicherCheckInData);
   325→      setTaeglicheEintraege(taeglicheEintraegeData);
   326→    } catch (err) {
   327→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   328→    } finally {
   329→      setLoading(false);
   330→    }
   331→  }, []);
   332→
   333→  useEffect(() => { fetchAll(); }, [fetchAll]);
   334→
   335→  const gewohnheitenVerwaltungMap = useMemo(() => {
   336→    const m = new Map<string, GewohnheitenVerwaltung>();
   337→    gewohnheitenVerwaltung.forEach(r => m.set(r.record_id, r));
   338→    return m;
   339→  }, [gewohnheitenVerwaltung]);
   340→
   341→  return { gewohnheitenVerwaltung, setGewohnheitenVerwaltung, taeglicherCheckIn, setTaeglicherCheckIn, taeglicheEintraege, setTaeglicheEintraege, loading, error, fetchAll, gewohnheitenVerwaltungMap };
   342→}
   343→```
