   361→import type { EnrichedTaeglicheEintraege, EnrichedTaeglicherCheckIn } from '@/types/enriched';
   362→import type { GewohnheitenVerwaltung, TaeglicheEintraege, TaeglicherCheckIn } from '@/types/app';
   363→import { extractRecordId } from '@/services/livingAppsService';
   364→
   365→// eslint-disable-next-line @typescript-eslint/no-explicit-any
   366→function resolveDisplay(url: string | undefined, map: Map<string, any>, ...fields: string[]): string {
   367→  if (!url) return '';
   368→  const id = extractRecordId(url);
   369→  if (!id) return '';
   370→  const r = map.get(id);
   371→  if (!r) return '';
   372→  return fields.map(f => String(r.fields[f] ?? '')).join(' ').trim();
   373→}
   374→
   375→interface TaeglicherCheckInMaps {
   376→  gewohnheitenVerwaltungMap: Map<string, GewohnheitenVerwaltung>;
   377→}
   378→
   379→export function enrichTaeglicherCheckIn(
   380→  taeglicherCheckIn: TaeglicherCheckIn[],
   381→  maps: TaeglicherCheckInMaps
   382→): EnrichedTaeglicherCheckIn[] {
   383→  return taeglicherCheckIn.map(r => ({
   384→    ...r,
   385→    gewohnheitenName: resolveDisplay(r.fields.gewohnheiten, maps.gewohnheitenVerwaltungMap, 'gewohnheit_name'),
   386→  }));
   387→}
   388→
   389→interface TaeglicheEintraegeMaps {
   390→  gewohnheitenVerwaltungMap: Map<string, GewohnheitenVerwaltung>;
   391→}
   392→
   393→export function enrichTaeglicheEintraege(
   394→  taeglicheEintraege: TaeglicheEintraege[],
   395→  maps: TaeglicheEintraegeMaps
   396→): EnrichedTaeglicheEintraege[] {
   397→  return taeglicheEintraege.map(r => ({
   398→    ...r,
   399→    gewohnheitName: resolveDisplay(r.fields.gewohnheit, maps.gewohnheitenVerwaltungMap, 'gewohnheit_name'),
   400→  }));
   401→}
