     1→import { useDashboardData } from '@/hooks/useDashboardData';
     2→import { enrichTaeglicheEintraege } from '@/lib/enrich';
     3→import { LivingAppsService, createRecordUrl, extractRecordId } from '@/services/livingAppsService';
     4→import { APP_IDS } from '@/types/app';
     5→import type { GewohnheitenVerwaltung, TaeglicheEintraege } from '@/types/app';
     6→import { Skeleton } from '@/components/ui/skeleton';
     7→import { Button } from '@/components/ui/button';
     8→import { Badge } from '@/components/ui/badge';
     9→import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
    10→import { Input } from '@/components/ui/input';
    11→import { Label } from '@/components/ui/label';
    12→import { Textarea } from '@/components/ui/textarea';
    13→import {
    14→  AlertCircle, CheckCircle2, Circle, Plus, Pencil, Trash2, Clock, Target, TrendingUp, Flame, ChevronRight
    15→} from 'lucide-react';
    16→import { useState, useMemo } from 'react';
    17→import { format, subDays, parseISO } from 'date-fns';
    18→import { de } from 'date-fns/locale';
    19→import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
    20→
    21→const TODAY = format(new Date(), 'yyyy-MM-dd');
    22→
    23→// --- Types ---
    24→interface HabitForm {
    25→  gewohnheit_name: string;
    26→  beschreibung: string;
    27→  zielzeit_minuten: string;
    28→}
    29→
    30→// --- Main Dashboard ---
    31→export default function DashboardOverview() {
    32→  const {
    33→    gewohnheitenVerwaltung, taeglicheEintraege,
    34→    gewohnheitenVerwaltungMap,
    35→    loading, error, fetchAll,
    36→  } = useDashboardData();
    37→
    38→  const enrichedEintraege = enrichTaeglicheEintraege(taeglicheEintraege, { gewohnheitenVerwaltungMap });
    39→
    40→  // Dialog state
    41→  const [habitDialogOpen, setHabitDialogOpen] = useState(false);
    42→  const [editingHabit, setEditingHabit] = useState<GewohnheitenVerwaltung | null>(null);
    43→  const [deleteHabitId, setDeleteHabitId] = useState<string | null>(null);
    44→  const [saving, setSaving] = useState(false);
    45→  const [habitForm, setHabitForm] = useState<HabitForm>({ gewohnheit_name: '', beschreibung: '', zielzeit_minuten: '' });
    46→
    47→  // Today's entries per habit
    48→  const todayEntriesMap = useMemo(() => {
    49→    const m = new Map<string, TaeglicheEintraege>();
    50→    taeglicheEintraege.forEach(e => {
    51→      if (e.fields.datum === TODAY) {
    52→        const hId = extractRecordId(e.fields.gewohnheit);
    53→        if (hId) m.set(hId, e);
    54→      }
    55→    });
    56→    return m;
    57→  }, [taeglicheEintraege]);
    58→
    59→  // Stats
    60→  const totalHabits = gewohnheitenVerwaltung.length;
    61→  const doneTodayCount = useMemo(() => {
    62→    let count = 0;
    63→    todayEntriesMap.forEach(e => { if (e.fields.ausgefuehrt) count++; });
    64→    return count;
    65→  }, [todayEntriesMap]);
    66→
    67→  const totalMinutesToday = useMemo(() => {
    68→    let sum = 0;
    69→    todayEntriesMap.forEach(e => { sum += e.fields.investierte_zeit_minuten ?? 0; });
    70→    return sum;
    71→  }, [todayEntriesMap]);
    72→
    73→  // Streak: days in a row with at least 1 habit done
    74→  const streak = useMemo(() => {
    75→    let count = 0;
    76→    for (let i = 0; i < 30; i++) {
    77→      const d = format(subDays(new Date(), i), 'yyyy-MM-dd');
    78→      const hasAny = taeglicheEintraege.some(e => e.fields.datum === d && e.fields.ausgefuehrt);
    79→      if (hasAny) count++;
    80→      else if (i > 0) break; // only break if not today (today might not be done yet)
    81→    }
    82→    return count;
    83→  }, [taeglicheEintraege]);
    84→
    85→  // Last 7 days chart data
    86→  const weekData = useMemo(() => {
    87→    return Array.from({ length: 7 }, (_, i) => {
    88→      const d = format(subDays(new Date(), 6 - i), 'yyyy-MM-dd');
    89→      const label = format(subDays(new Date(), 6 - i), 'EEE', { locale: de });
    90→      const done = taeglicheEintraege.filter(e => e.fields.datum === d && e.fields.ausgefuehrt).length;
    91→      const total = gewohnheitenVerwaltung.length;
    92→      return { day: label, done, total, date: d };
    93→    });
    94→  }, [taeglicheEintraege, gewohnheitenVerwaltung]);
    95→
    96→  // Toggle habit done for today
    97→  const handleToggleHabit = async (habit: GewohnheitenVerwaltung) => {
    98→    const existing = todayEntriesMap.get(habit.record_id);
    99→    setSaving(true);
   100→    try {
   101→      if (existing) {
   102→        const newVal = !existing.fields.ausgefuehrt;
   103→        await LivingAppsService.updateTaeglicheEintraegeEntry(existing.record_id, {
   104→          ausgefuehrt: newVal,
   105→        });
   106→      } else {
   107→        await LivingAppsService.createTaeglicheEintraegeEntry({
   108→          datum: TODAY,
   109→          gewohnheit: createRecordUrl(APP_IDS.GEWOHNHEITEN_VERWALTUNG, habit.record_id),
   110→          ausgefuehrt: true,
   111→          investierte_zeit_minuten: habit.fields.zielzeit_minuten ?? 0,
   112→        });
   113→      }
   114→      fetchAll();
   115→    } finally {
   116→      setSaving(false);
   117→    }
   118→  };
   119→
   120→  // Update invested time
   121→  const handleTimeUpdate = async (habit: GewohnheitenVerwaltung, minutes: number) => {
   122→    const existing = todayEntriesMap.get(habit.record_id);
   123→    try {
   124→      if (existing) {
   125→        await LivingAppsService.updateTaeglicheEintraegeEntry(existing.record_id, {
   126→          investierte_zeit_minuten: minutes,
   127→        });
   128→      } else {
   129→        await LivingAppsService.createTaeglicheEintraegeEntry({
   130→          datum: TODAY,
   131→          gewohnheit: createRecordUrl(APP_IDS.GEWOHNHEITEN_VERWALTUNG, habit.record_id),
   132→          ausgefuehrt: false,
   133→          investierte_zeit_minuten: minutes,
   134→        });
   135→      }
   136→      fetchAll();
   137→    } catch {}
   138→  };
   139→
   140→  // Habit CRUD
   141→  const openCreateHabit = () => {
   142→    setEditingHabit(null);
   143→    setHabitForm({ gewohnheit_name: '', beschreibung: '', zielzeit_minuten: '' });
   144→    setHabitDialogOpen(true);
   145→  };
   146→
   147→  const openEditHabit = (h: GewohnheitenVerwaltung) => {
   148→    setEditingHabit(h);
   149→    setHabitForm({
   150→      gewohnheit_name: h.fields.gewohnheit_name ?? '',
   151→      beschreibung: h.fields.beschreibung ?? '',
   152→      zielzeit_minuten: String(h.fields.zielzeit_minuten ?? ''),
   153→    });
   154→    setHabitDialogOpen(true);
   155→  };
   156→
   157→  const handleSaveHabit = async () => {
   158→    setSaving(true);
   159→    try {
   160→      const fields = {
   161→        gewohnheit_name: habitForm.gewohnheit_name,
   162→        beschreibung: habitForm.beschreibung || undefined,
   163→        zielzeit_minuten: habitForm.zielzeit_minuten ? Number(habitForm.zielzeit_minuten) : undefined,
   164→      };
   165→      if (editingHabit) {
   166→        await LivingAppsService.updateGewohnheitenVerwaltungEntry(editingHabit.record_id, fields);
   167→      } else {
   168→        await LivingAppsService.createGewohnheitenVerwaltungEntry(fields);
   169→      }
   170→      fetchAll();
   171→      setHabitDialogOpen(false);
   172→    } finally {
   173→      setSaving(false);
   174→    }
   175→  };
   176→
   177→  const handleDeleteHabit = async () => {
   178→    if (!deleteHabitId) return;
   179→    setSaving(true);
   180→    try {
   181→      await LivingAppsService.deleteGewohnheitenVerwaltungEntry(deleteHabitId);
   182→      fetchAll();
   183→      setDeleteHabitId(null);
   184→    } finally {
   185→      setSaving(false);
   186→    }
   187→  };
   188→
   189→  if (loading) return <DashboardSkeleton />;
   190→  if (error) return <DashboardError error={error} onRetry={fetchAll} />;
   191→
   192→  const completionPct = totalHabits > 0 ? Math.round((doneTodayCount / totalHabits) * 100) : 0;
   193→
   194→  return (
   195→    <div className="space-y-6 pb-8">
   196→      {/* Header */}
   197→      <div className="flex items-center justify-between">
   198→        <div>
   199→          <h1 className="text-2xl font-bold text-foreground tracking-tight">
   200→            {format(new Date(), 'EEEE, d. MMMM', { locale: de })}
   201→          </h1>
   202→          <p className="text-sm text-muted-foreground mt-0.5">
   203→            {doneTodayCount === 0
   204→              ? 'Leg los — deine Gewohnheiten warten!'
   205→              : doneTodayCount === totalHabits
   206→              ? 'Alle Gewohnheiten erledigt! 🎉'
   207→              : `${doneTodayCount} von ${totalHabits} erledigt`}
   208→          </p>
   209→        </div>
   210→        <Button onClick={openCreateHabit} size="sm" className="gap-2">
   211→          <Plus size={14} />
   212→          Neue Gewohnheit
   213→        </Button>
   214→      </div>
   215→
   216→      {/* KPI Strip */}
   217→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   218→        <div className="bg-card border rounded-2xl p-4">
   219→          <div className="flex items-center gap-2 mb-2">
   220→            <div className="w-7 h-7 rounded-lg bg-primary/10 flex items-center justify-center">
   221→              <Target size={13} className="text-primary" />
   222→            </div>
   223→            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Heute</span>
   224→          </div>
   225→          <div className="text-2xl font-bold text-foreground">{doneTodayCount}<span className="text-sm font-normal text-muted-foreground">/{totalHabits}</span></div>
   226→          <div className="mt-2 h-1.5 bg-muted rounded-full overflow-hidden">
   227→            <div
   228→              className="h-full bg-primary rounded-full transition-all duration-500"
   229→              style={{ width: `${completionPct}%` }}
   230→            />
   231→          </div>
   232→        </div>
   233→
   234→        <div className="bg-card border rounded-2xl p-4">
   235→          <div className="flex items-center gap-2 mb-2">
   236→            <div className="w-7 h-7 rounded-lg bg-orange-500/10 flex items-center justify-center">
   237→              <Flame size={13} className="text-orange-500" />
   238→            </div>
   239→            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Serie</span>
   240→          </div>
   241→          <div className="text-2xl font-bold text-foreground">{streak}<span className="text-sm font-normal text-muted-foreground"> Tage</span></div>
   242→          <p className="text-xs text-muted-foreground mt-1">aktuelle Streak</p>
   243→        </div>
   244→
   245→        <div className="bg-card border rounded-2xl p-4">
   246→          <div className="flex items-center gap-2 mb-2">
   247→            <div className="w-7 h-7 rounded-lg bg-emerald-500/10 flex items-center justify-center">
   248→              <Clock size={13} className="text-emerald-500" />
   249→            </div>
   250→            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Zeit heute</span>
   251→          </div>
   252→          <div className="text-2xl font-bold text-foreground">{totalMinutesToday}<span className="text-sm font-normal text-muted-foreground"> min</span></div>
   253→          <p className="text-xs text-muted-foreground mt-1">investiert</p>
   254→        </div>
   255→
   256→        <div className="bg-card border rounded-2xl p-4">
   257→          <div className="flex items-center gap-2 mb-2">
   258→            <div className="w-7 h-7 rounded-lg bg-violet-500/10 flex items-center justify-center">
   259→              <TrendingUp size={13} className="text-violet-500" />
   260→            </div>
   261→            <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Fortschritt</span>
   262→          </div>
   263→          <div className="text-2xl font-bold text-foreground">{completionPct}<span className="text-sm font-normal text-muted-foreground">%</span></div>
   264→          <p className="text-xs text-muted-foreground mt-1">heute erledigt</p>
   265→        </div>
   266→      </div>
   267→
   268→      {/* Main Layout: habit board + chart */}
   269→      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
   270→        {/* Habit Checklist — hero */}
   271→        <div className="lg:col-span-2 bg-card border rounded-2xl overflow-hidden">
   272→          <div className="px-5 py-4 border-b flex items-center justify-between">
   273→            <h2 className="font-semibold text-foreground text-base">Heutige Gewohnheiten</h2>
   274→            <Badge variant="secondary" className="text-xs">{doneTodayCount}/{totalHabits}</Badge>
   275→          </div>
   276→
   277→          {gewohnheitenVerwaltung.length === 0 ? (
   278→            <div className="flex flex-col items-center justify-center py-16 gap-3 text-center px-6">
   279→              <div className="w-12 h-12 rounded-2xl bg-muted flex items-center justify-center">
   280→                <Target size={20} className="text-muted-foreground" />
   281→              </div>
   282→              <p className="font-medium text-foreground">Noch keine Gewohnheiten</p>
   283→              <p className="text-sm text-muted-foreground max-w-xs">Erstelle deine erste Gewohnheit und starte deinen Tracker.</p>
   284→              <Button size="sm" variant="outline" onClick={openCreateHabit} className="gap-2 mt-1">
   285→                <Plus size={13} />
   286→                Gewohnheit erstellen
   287→              </Button>
   288→            </div>
   289→          ) : (
   290→            <ul className="divide-y divide-border">
   291→              {gewohnheitenVerwaltung.map(habit => {
   292→                const entry = todayEntriesMap.get(habit.record_id);
   293→                const done = entry?.fields.ausgefuehrt ?? false;
   294→                const investedMin = entry?.fields.investierte_zeit_minuten ?? 0;
   295→                const goalMin = habit.fields.zielzeit_minuten ?? 0;
   296→                const progress = goalMin > 0 ? Math.min(100, Math.round((investedMin / goalMin) * 100)) : null;
   297→
   298→                return (
   299→                  <li key={habit.record_id} className={`group flex items-center gap-4 px-5 py-4 transition-colors ${done ? 'bg-primary/5' : 'hover:bg-muted/30'}`}>
   300→                    {/* Check button */}
   301→                    <button
   302→                      onClick={() => handleToggleHabit(habit)}
   303→                      disabled={saving}
   304→                      className="shrink-0 transition-transform active:scale-90"
   305→                      aria-label={done ? 'Als unerledigt markieren' : 'Als erledigt markieren'}
   306→                    >
   307→                      {done
   308→                        ? <CheckCircle2 size={26} className="text-primary" />
   309→                        : <Circle size={26} className="text-muted-foreground/50 hover:text-primary/60 transition-colors" />
   310→                      }
   311→                    </button>
   312→
   313→                    {/* Content */}
   314→                    <div className="flex-1 min-w-0">
   315→                      <div className="flex items-center gap-2">
   316→                        <span className={`font-medium text-sm ${done ? 'line-through text-muted-foreground' : 'text-foreground'}`}>
   317→                          {habit.fields.gewohnheit_name ?? '—'}
   318→                        </span>
   319→                        {done && <Badge variant="secondary" className="text-[10px] px-1.5 py-0">Erledigt</Badge>}
   320→                      </div>
   321→                      {habit.fields.beschreibung && (
   322→                        <p className="text-xs text-muted-foreground mt-0.5 truncate">{habit.fields.beschreibung}</p>
   323→                      )}
   324→                      {/* Time progress bar */}
   325→                      {goalMin > 0 && (
   326→                        <div className="flex items-center gap-2 mt-1.5">
   327→                          <div className="flex-1 h-1 bg-muted rounded-full overflow-hidden">
   328→                            <div
   329→                              className={`h-full rounded-full transition-all duration-500 ${done ? 'bg-primary' : 'bg-muted-foreground/30'}`}
   330→                              style={{ width: `${progress ?? 0}%` }}
   331→                            />
   332→                          </div>
   333→                          <TimeInput
   334→                            value={investedMin}
   335→                            goal={goalMin}
   336→                            onChange={m => handleTimeUpdate(habit, m)}
   337→                          />
   338→                        </div>
   339→                      )}
   340→                    </div>
   341→
   342→                    {/* Actions */}
   343→                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
   344→                      <button
   345→                        onClick={() => openEditHabit(habit)}
   346→                        className="p-1.5 rounded-lg hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
   347→                        aria-label="Bearbeiten"
   348→                      >
   349→                        <Pencil size={13} />
   350→                      </button>
   351→                      <button
   352→                        onClick={() => setDeleteHabitId(habit.record_id)}
   353→                        className="p-1.5 rounded-lg hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors"
   354→                        aria-label="Löschen"
   355→                      >
   356→                        <Trash2 size={13} />
   357→                      </button>
   358→                    </div>
   359→                  </li>
   360→                );
   361→              })}
   362→            </ul>
   363→          )}
   364→        </div>
   365→
   366→        {/* Right sidebar */}
   367→        <div className="flex flex-col gap-4">
   368→          {/* 7-day bar chart */}
   369→          <div className="bg-card border rounded-2xl p-5">
   370→            <h3 className="font-semibold text-sm text-foreground mb-4">Letzte 7 Tage</h3>
   371→            {gewohnheitenVerwaltung.length === 0 ? (
   372→              <div className="h-32 flex items-center justify-center text-xs text-muted-foreground">Keine Daten</div>
   373→            ) : (
   374→              <ResponsiveContainer width="100%" height={140}>
   375→                <BarChart data={weekData} barSize={18}>
   376→                  <XAxis dataKey="day" tick={{ fontSize: 10, fill: 'var(--muted-foreground)' }} axisLine={false} tickLine={false} />
   377→                  <YAxis hide domain={[0, Math.max(totalHabits, 1)]} />
   378→                  <Tooltip
   379→                    contentStyle={{ backgroundColor: 'var(--card)', border: '1px solid var(--border)', borderRadius: 8, fontSize: 12 }}
   380→                    formatter={(v: number) => [`${v} erledigt`, '']}
   381→                    labelFormatter={(l) => l}
   382→                    cursor={{ fill: 'var(--muted)', radius: 4 }}
   383→                  />
   384→                  <Bar dataKey="done" radius={[4, 4, 0, 0]}>
   385→                    {weekData.map((entry, i) => (
   386→                      <Cell
   387→                        key={i}
   388→                        fill={entry.date === TODAY ? 'var(--primary)' : entry.done > 0 ? 'var(--primary)' : 'var(--muted)'}
   389→                        opacity={entry.date === TODAY ? 1 : entry.done > 0 ? 0.5 : 0.25}
   390→                      />
   391→                    ))}
   392→                  </Bar>
   393→                </BarChart>
   394→              </ResponsiveContainer>
   395→            )}
   396→          </div>
   397→
   398→          {/* Habit details / goal overview */}
   399→          {gewohnheitenVerwaltung.length > 0 && (
   400→            <div className="bg-card border rounded-2xl p-5">
   401→              <h3 className="font-semibold text-sm text-foreground mb-3">Zielzeiten</h3>
   402→              <div className="space-y-3">
   403→                {gewohnheitenVerwaltung.slice(0, 5).map(habit => {
   404→                  const entry = todayEntriesMap.get(habit.record_id);
   405→                  const invested = entry?.fields.investierte_zeit_minuten ?? 0;
   406→                  const goal = habit.fields.zielzeit_minuten ?? 0;
   407→                  const pct = goal > 0 ? Math.min(100, Math.round((invested / goal) * 100)) : 0;
   408→                  const done = entry?.fields.ausgefuehrt ?? false;
   409→                  return (
   410→                    <div key={habit.record_id} className="space-y-1">
   411→                      <div className="flex items-center justify-between text-xs">
   412→                        <span className={`font-medium truncate max-w-[120px] ${done ? 'text-primary' : 'text-foreground'}`}>
   413→                          {habit.fields.gewohnheit_name ?? '—'}
   414→                        </span>
   415→                        {goal > 0 ? (
   416→                          <span className="text-muted-foreground shrink-0">{invested}/{goal} min</span>
   417→                        ) : (
   418→                          <span className="text-muted-foreground shrink-0">kein Ziel</span>
   419→                        )}
   420→                      </div>
   421→                      {goal > 0 && (
   422→                        <div className="h-1.5 bg-muted rounded-full overflow-hidden">
   423→                          <div
   424→                            className={`h-full rounded-full transition-all duration-500 ${done ? 'bg-primary' : 'bg-primary/40'}`}
   425→                            style={{ width: `${pct}%` }}
   426→                          />
   427→                        </div>
   428→                      )}
   429→                    </div>
   430→                  );
   431→                })}
   432→                {gewohnheitenVerwaltung.length > 5 && (
   433→                  <p className="text-xs text-muted-foreground text-center pt-1">
   434→                    +{gewohnheitenVerwaltung.length - 5} weitere
   435→                  </p>
   436→                )}
   437→              </div>
   438→            </div>
   439→          )}
   440→        </div>
   441→      </div>
   442→
   443→      {/* Habit Create/Edit Dialog */}
   444→      <Dialog open={habitDialogOpen} onOpenChange={setHabitDialogOpen}>
   445→        <DialogContent className="max-w-md">
   446→          <DialogHeader>
   447→            <DialogTitle>{editingHabit ? 'Gewohnheit bearbeiten' : 'Neue Gewohnheit'}</DialogTitle>
   448→          </DialogHeader>
   449→          <div className="space-y-4 py-2">
   450→            <div className="space-y-1.5">
   451→              <Label htmlFor="habit-name">Name der Gewohnheit *</Label>
   452→              <Input
   453→                id="habit-name"
   454→                placeholder="z. B. Morgenmeditation"
   455→                value={habitForm.gewohnheit_name}
   456→                onChange={e => setHabitForm(f => ({ ...f, gewohnheit_name: e.target.value }))}
   457→                autoFocus
   458→              />
   459→            </div>
   460→            <div className="space-y-1.5">
   461→              <Label htmlFor="habit-desc">Beschreibung</Label>
   462→              <Textarea
   463→                id="habit-desc"
   464→                placeholder="Worum geht es bei dieser Gewohnheit?"
   465→                rows={2}
   466→                value={habitForm.beschreibung}
   467→                onChange={e => setHabitForm(f => ({ ...f, beschreibung: e.target.value }))}
   468→              />
   469→            </div>
   470→            <div className="space-y-1.5">
   471→              <Label htmlFor="habit-time">Zielzeit pro Tag (Minuten)</Label>
   472→              <Input
   473→                id="habit-time"
   474→                type="number"
   475→                min={1}
   476→                placeholder="z. B. 30"
   477→                value={habitForm.zielzeit_minuten}
   478→                onChange={e => setHabitForm(f => ({ ...f, zielzeit_minuten: e.target.value }))}
   479→              />
   480→            </div>
   481→          </div>
   482→          <DialogFooter>
   483→            <Button variant="outline" onClick={() => setHabitDialogOpen(false)}>Abbrechen</Button>
   484→            <Button onClick={handleSaveHabit} disabled={saving || !habitForm.gewohnheit_name.trim()}>
   485→              {saving ? 'Speichern...' : editingHabit ? 'Speichern' : 'Erstellen'}
   486→            </Button>
   487→          </DialogFooter>
   488→        </DialogContent>
   489→      </Dialog>
   490→
   491→      {/* Delete Confirm Dialog */}
   492→      <Dialog open={!!deleteHabitId} onOpenChange={v => !v && setDeleteHabitId(null)}>
   493→        <DialogContent className="max-w-sm">
   494→          <DialogHeader>
   495→            <DialogTitle>Gewohnheit löschen?</DialogTitle>
   496→          </DialogHeader>
   497→          <p className="text-sm text-muted-foreground">Diese Aktion kann nicht rückgängig gemacht werden.</p>
   498→          <DialogFooter>
   499→            <Button variant="outline" onClick={() => setDeleteHabitId(null)}>Abbrechen</Button>
   500→            <Button variant="destructive" onClick={handleDeleteHabit} disabled={saving}>
   501→              {saving ? 'Löschen...' : 'Löschen'}
   502→            </Button>
   503→          </DialogFooter>
   504→        </DialogContent>
   505→      </Dialog>
   506→    </div>
   507→  );
   508→}
   509→
   510→// Inline time input component
   511→function TimeInput({ value, goal, onChange }: { value: number; goal: number; onChange: (m: number) => void }) {
   512→  const [editing, setEditing] = useState(false);
   513→  const [temp, setTemp] = useState(String(value));
   514→
   515→  const commit = () => {
   516→    const parsed = parseInt(temp, 10);
   517→    if (!isNaN(parsed) && parsed >= 0) onChange(parsed);
   518→    setEditing(false);
   519→  };
   520→
   521→  if (editing) {
   522→    return (
   523→      <input
   524→        className="w-14 text-xs border rounded px-1 py-0.5 bg-background text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
   525→        type="number"
   526→        min={0}
   527→        value={temp}
   528→        onChange={e => setTemp(e.target.value)}
   529→        onBlur={commit}
   530→        onKeyDown={e => e.key === 'Enter' && commit()}
   531→        autoFocus
   532→      />
   533→    );
   534→  }
   535→
   536→  return (
   537→    <button
   538→      className="text-xs text-muted-foreground hover:text-foreground transition-colors shrink-0 tabular-nums"
   539→      onClick={() => { setTemp(String(value)); setEditing(true); }}
   540→    >
   541→      {value}/{goal} min
   542→    </button>
   543→  );
   544→}
   545→
   546→// --- Skeleton & Error ---
   547→function DashboardSkeleton() {
   548→  return (
   549→    <div className="space-y-6">
   550→      <div className="flex items-center justify-between">
   551→        <Skeleton className="h-8 w-48" />
   552→        <Skeleton className="h-9 w-36" />
   553→      </div>
   554→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   555→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   556→      </div>
   557→      <Skeleton className="h-64 rounded-2xl" />
   558→    </div>
   559→  );
   560→}
   561→
   562→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   563→  return (
   564→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   565→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   566→        <AlertCircle size={22} className="text-destructive" />
   567→      </div>
   568→      <div className="text-center">
   569→        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
   570→        <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
